  ThreadsCompanion copyWith({
    Value<String>? threadId,
    Value<String>? boardId,
    Value<String>? title,
    Value<String>? authorId,
    Value<String?>? pollJson,
    Value<String?>? pollResultsJson,
    Value<DateTime>? createdAt,
