class RemoteNode extends DataClass implements Insertable<RemoteNode> {
  final String nodeId;
  final String name;
  final String url;
  final String? accessToken;
  final int syncCursor;
  final DateTime? lastSyncAt;
  final DateTime createdAt;
  final DateTime updatedAt;
  final bool isActive;

  /// Host-declared constitution compliance level ("full"/"partial"/...),
  /// captured from the host's own metadata at add/refresh time. Null = never
  /// fetched; "unknown" = fetched but undeclared. Compliance-review gap #2.
  final String? constitutionCompliance;
  const RemoteNode({
    required this.nodeId,
    required this.name,
    required this.url,
    this.accessToken,
    required this.syncCursor,
    this.lastSyncAt,
    required this.createdAt,
    required this.updatedAt,
    required this.isActive,
    this.constitutionCompliance,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['node_id'] = Variable<String>(nodeId);
    map['name'] = Variable<String>(name);
    map['url'] = Variable<String>(url);
    if (!nullToAbsent || accessToken != null) {
      map['access_token'] = Variable<String>(accessToken);
    }
    map['sync_cursor'] = Variable<int>(syncCursor);
    if (!nullToAbsent || lastSyncAt != null) {
      map['last_sync_at'] = Variable<DateTime>(lastSyncAt);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    map['is_active'] = Variable<bool>(isActive);
    if (!nullToAbsent || constitutionCompliance != null) {
      map['constitution_compliance'] = Variable<String>(constitutionCompliance);
    }
    return map;
  }

  RemoteNodesCompanion toCompanion(bool nullToAbsent) {
    return RemoteNodesCompanion(
      nodeId: Value(nodeId),
      name: Value(name),
      url: Value(url),
      accessToken: accessToken == null && nullToAbsent
          ? const Value.absent()
          : Value(accessToken),
      syncCursor: Value(syncCursor),
      lastSyncAt: lastSyncAt == null && nullToAbsent
          ? const Value.absent()
          : Value(lastSyncAt),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      isActive: Value(isActive),
      constitutionCompliance: constitutionCompliance == null && nullToAbsent
          ? const Value.absent()
          : Value(constitutionCompliance),
    );
  }

  factory RemoteNode.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return RemoteNode(
      nodeId: serializer.fromJson<String>(json['nodeId']),
      name: serializer.fromJson<String>(json['name']),
      url: serializer.fromJson<String>(json['url']),
