    : super(
        TableManagerState(
          db: db,
          table: table,
          createFilteringComposer: () =>
              $$ThreadsTableFilterComposer($db: db, $table: table),
          createOrderingComposer: () =>
              $$ThreadsTableOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $$ThreadsTableAnnotationComposer($db: db, $table: table),
          updateCompanionCallback:
              ({
                Value<String> threadId = const Value.absent(),
                Value<String> boardId = const Value.absent(),
                Value<String> title = const Value.absent(),
                Value<String> authorId = const Value.absent(),
                Value<String?> pollJson = const Value.absent(),
                Value<String?> pollResultsJson = const Value.absent(),
                Value<DateTime> createdAt = const Value.absent(),
                Value<DateTime> updatedAt = const Value.absent(),
                Value<bool> isDeleted = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => ThreadsCompanion(
                threadId: threadId,
                boardId: boardId,
                title: title,
                authorId: authorId,
                pollJson: pollJson,
                pollResultsJson: pollResultsJson,
                createdAt: createdAt,
                updatedAt: updatedAt,
                isDeleted: isDeleted,
                rowid: rowid,
              ),
          createCompanionCallback:
              ({
                required String threadId,
                required String boardId,
                required String title,
                required String authorId,
                Value<String?> pollJson = const Value.absent(),
                Value<String?> pollResultsJson = const Value.absent(),
                required DateTime createdAt,
                required DateTime updatedAt,
                Value<bool> isDeleted = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => ThreadsCompanion.insert(
                threadId: threadId,
                boardId: boardId,
                title: title,
                authorId: authorId,
                pollJson: pollJson,
                pollResultsJson: pollResultsJson,
                createdAt: createdAt,
                updatedAt: updatedAt,
                isDeleted: isDeleted,
                rowid: rowid,
              ),
          withReferenceMapper: (p0) => p0
              .map(
                (e) => (
                  e.readTable(table),
                  $$ThreadsTableReferences(db, table, e),
                ),
              )
              .toList(),
          prefetchHooksCallback:
              ({
                boardId = false,
                postsRefs = false,
                postMetadataRefs = false,
                discussionMetadataRefs = false,
              }) {
                return PrefetchHooks(
                  db: db,
                  explicitlyWatchedTables: [
                    if (postsRefs) db.posts,
                    if (postMetadataRefs) db.postMetadata,
                    if (discussionMetadataRefs) db.discussionMetadata,
                  ],
                  addJoins:
                      <
                        T extends TableManagerState<
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic
                        >
                      >(state) {
                        if (boardId) {
                          state =
                              state.withJoin(
                                    currentTable: table,
                                    currentColumn: table.boardId,
                                    referencedTable: $$ThreadsTableReferences
                                        ._boardIdTable(db),
                                    referencedColumn: $$ThreadsTableReferences
                                        ._boardIdTable(db)
                                        .boardId,
                                  )
                                  as T;
                        }

                        return state;
                      },
                  getPrefetchedDataCallback: (items) async {
                    return [
                      if (postsRefs)
                        await $_getPrefetchedData<Thread, $ThreadsTable, Post>(
                          currentTable: table,
                          referencedTable: $$ThreadsTableReferences
                              ._postsRefsTable(db),
                          managerFromTypedResult: (p0) =>
                              $$ThreadsTableReferences(db, table, p0).postsRefs,
                          referencedItemsForCurrentItem:
                              (item, referencedItems) => referencedItems.where(
                                (e) => e.threadId == item.threadId,
                              ),
                          typedResults: items,
                        ),
                      if (postMetadataRefs)
                        await $_getPrefetchedData<
                          Thread,
                          $ThreadsTable,
                          PostMetadataData
                        >(
                          currentTable: table,
                          referencedTable: $$ThreadsTableReferences
                              ._postMetadataRefsTable(db),
                          managerFromTypedResult: (p0) =>
                              $$ThreadsTableReferences(
                                db,
                                table,
                                p0,
                              ).postMetadataRefs,
                          referencedItemsForCurrentItem:
                              (item, referencedItems) => referencedItems.where(
                                (e) => e.threadId == item.threadId,
                              ),
                          typedResults: items,
                        ),
                      if (discussionMetadataRefs)
                        await $_getPrefetchedData<
                          Thread,
                          $ThreadsTable,
                          DiscussionMetadataData
                        >(
                          currentTable: table,
                          referencedTable: $$ThreadsTableReferences
                              ._discussionMetadataRefsTable(db),
                          managerFromTypedResult: (p0) =>
                              $$ThreadsTableReferences(
                                db,
                                table,
                                p0,
                              ).discussionMetadataRefs,
                          referencedItemsForCurrentItem:
                              (item, referencedItems) => referencedItems.where(
                                (e) => e.threadId == item.threadId,
                              ),
                          typedResults: items,
                        ),
                    ];
                  },
                );
              },
        ),
      );
